mapper.select:
SELECT COUNT(*) AS order_count, COALESCE(SUM(total_amount),0) AS order_pay_price
FROM trade_order
WHERE order_no=#{orderNo}

SELECT status, comment_status, COALESCE(delivery_type,1) AS delivery_type, COUNT(*) AS cnt
FROM trade_order WHERE member_id=#{memberId}
GROUP BY status, comment_status, COALESCE(delivery_type,1)
